// Data scoping: which Foundry projects (and optionally which agents) a user may see.
//
// Scopes come from runtime config (AGENTCTL_ACCESS_SCOPES, generated by Terraform from
// `access_scopes`) and are matched against the user's Entra group memberships.
//
// Enforcement model:
//  - Project scoping is *enforced by Azure*: Terraform grants each scope's groups "Foundry User"
//    only on that scope's projects, so the user's own token cannot read other projects' agents.
//    The UI filter mirrors this so nothing half-loads.
//  - Agent-name patterns are a UI refinement within a project (Foundry RBAC is per project).
//  - Telemetry in a shared Log Analytics workspace is readable by anyone with workspace access;
//    use per-team App Insights / workspaces when traces themselves must be isolated.

export interface AccessScopeConfig {
  name: string;
  /** Entra group object ids whose members get this scope. */
  groups: string[];
  /** "account/project" names, "*" for all projects. */
  projects: string[];
  /** Optional agent-name globs (e.g. "hr-*"); omitted = all agents in the projects. */
  agents?: string[];
}

export interface AccessConfig {
  scopes: AccessScopeConfig[];
  /** What a user in none of the scope groups sees. "all" keeps single-team setups simple. */
  unscopedDefault: "all" | "none";
}

export type ResolvedScope =
  | { all: true; names: string[] }
  | { all: false; names: string[]; projects: Set<string>; agentPatterns: RegExp[] | null };

/**
 * Agent-name glob -> anchored regex. Every regex metacharacter is escaped; only * and ? become
 * wildcards. Globs come from admin config and are length-capped and limited to 4 wildcards to
 * keep matching cheap (agent names are <= 63 chars).
 */
const glob = (g: string) => {
  const safe = g.slice(0, 64);
  if ((safe.match(/[*?]/g) ?? []).length > 4) {
    console.warn(`agentctl: agent glob "${safe}" has too many wildcards; it matches nothing`);
    return /(?!)/; // fail closed
  }
  const pattern = safe.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*/g, "[^]*").replace(/\?/g, "[^]");
  return new RegExp(`^${pattern}$`, "i"); // nosemgrep: detect-non-literal-regexp -- escaped, capped glob (see above)
};

export function resolveScope(cfg: AccessConfig, groupIds: string[], isAdmin: boolean): ResolvedScope {
  if (isAdmin) return { all: true, names: ["admin"] };
  const mine = new Set(groupIds.map((g) => g.toLowerCase()));
  const matched = cfg.scopes.filter((s) => s.groups.some((g) => mine.has(g.toLowerCase())));
  if (!matched.length) {
    return cfg.unscopedDefault === "all" || !cfg.scopes.length
      ? { all: true, names: [] }
      : { all: false, names: [], projects: new Set(), agentPatterns: null };
  }
  if (matched.some((s) => s.projects.includes("*") && !s.agents?.length)) return { all: true, names: matched.map((s) => s.name) };

  const projects = new Set<string>();
  const patterns: RegExp[] = [];
  let anyUnrestrictedAgents = false;
  for (const s of matched) {
    s.projects.forEach((p) => projects.add(p.toLowerCase()));
    if (s.agents?.length) s.agents.forEach((a) => patterns.push(glob(a)));
    else anyUnrestrictedAgents = true;
  }
  return { all: false, names: matched.map((s) => s.name), projects, agentPatterns: anyUnrestrictedAgents ? null : patterns };
}

export function projectAllowed(scope: ResolvedScope, account: string, project: string): boolean {
  if (scope.all) return true;
  return scope.projects.has("*") || scope.projects.has(`${account}/${project}`.toLowerCase());
}

export function agentAllowed(scope: ResolvedScope, agent: { account: string; project: string; name: string }): boolean {
  if (scope.all) return true;
  if (!projectAllowed(scope, agent.account, agent.project)) return false;
  return !scope.agentPatterns || scope.agentPatterns.some((r) => r.test(agent.name));
}

export function parseAccessConfig(raw: unknown): AccessConfig {
  const fallback: AccessConfig = { scopes: [], unscopedDefault: "all" };
  if (!raw || typeof raw !== "object") return fallback;
  const r = raw as Partial<AccessConfig>;
  const scopes = Array.isArray(r.scopes)
    ? r.scopes
        .filter((s) => s && typeof s.name === "string" && Array.isArray(s.groups) && Array.isArray(s.projects))
        .map((s) => ({ name: s.name, groups: s.groups.map(String), projects: s.projects.map(String), agents: Array.isArray(s.agents) ? s.agents.map(String) : undefined }))
    : [];
  return { scopes, unscopedDefault: r.unscopedDefault === "none" ? "none" : "all" };
}
